#!/usr/bin/env bash
# AKFC — « Contacts » devient « Nous contacter » (URL /contacts inchangée) + texte modifiable.
#  - libellé du menu, de « Pages éditoriales », du titre par défaut et de l'onglet ;
#    le titre enregistré « Contacts » est renommé au démarrage (un titre personnalisé est gardé).
#  - texte d'introduction de départ en VRAI bloc du constructeur (créé si la page est absente ou
#    sans bloc ; jamais réécrit) : à quoi sert le formulaire, choix « Gestion du club » / « Support
#    du site », accusé de réception. Plus de phrase figée dans le code.
#  Preuve avant commit : pnpm check (sinon TOUT est restauré).
# Usage : bash fix-contacts-page.sh   (AKFC_APPLY_ONLY=1 : applique sans vérifier ni committer)
set -euo pipefail
[ -f "package.json" ] || { echo "ERREUR: racine du repo." >&2; exit 1; }
SVC="packages/backend/src/modules/sitePages/ensureContactsPage.service.ts"
[ -f "$SVC" ] && { echo "— déjà appliqué"; exit 0; }
[ -f packages/backend/src/modules/sitePages/ensureInscriptionPage.service.ts ] || { echo "ERREUR: applique d'abord fix-inscription-editable.sh." >&2; exit 1; }
FILES=("apps/web/src/app/(public)/contacts/page.tsx" apps/web/src/features/app-shell/navEntries.ts apps/web/src/config/pageRegistry.ts "apps/web/src/app/(admin)/dashboard/site-pages/[slug]/page.tsx" apps/web/src/instrumentation.ts)
BK=/tmp/akfc_cp_backup; rm -rf "$BK"; mkdir -p "$BK"
for f in "${FILES[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$f" "$BK/$f"; done
restore(){ for f in "${FILES[@]}"; do cp "$BK/$f" "$f"; done; rm -f "$SVC"; echo "↩ fichiers restaurés à l'identique (aucun commit)."; }
W=/tmp/akfc_cp; rm -rf "$W"; mkdir -p "$W"
echo '' | base64 -d > "$W/edit.py"
echo "== application =="
echo '' | base64 -d > "$SVC" && echo "  ok  $SVC"
python3 "$W/edit.py" . || { restore; exit 1; }
if [ "${AKFC_APPLY_ONLY:-0}" = "1" ]; then echo "APPLY_ONLY"; exit 0; fi
echo "== pnpm check =="
if ! pnpm check > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"; grep -nE "conventions Next|error TS|Error:" /tmp/akfc_tc.log | head -15; restore; exit 1
fi
echo "  ✅ check OK"
git add "$SVC" "${FILES[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
feat(contacts): « Nous contacter », texte d'introduction modifiable dans le constructeur

